<style>
.inn-feedback-wrap {
  max-width: 640px;
  margin: 48px auto 64px auto;
  padding: 32px 28px;
  border: 1px solid var(--bs-border-color, #dee2e6);
  border-radius: 12px;
}
.inn-feedback-wrap h1 {
  font-size: 1.6rem;
  margin-bottom: 16px;
}
.inn-feedback-wrap p {
  line-height: 1.65;
}
.inn-feedback-field {
  margin-top: 20px;
}
.inn-feedback-field label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
}
.inn-feedback-field input {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  border: 1px solid var(--bs-border-color, #ced4da);
  border-radius: 8px;
  background: var(--bs-body-bg, #fff);
  color: var(--bs-body-color, #212529);
  box-sizing: border-box;
}
.inn-feedback-btn {
  margin-top: 20px;
  padding: 12px 28px;
  font-size: 1.05rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  background: #0d6efd;
  color: #fff;
